c026.try_sql:
-- A condition on a group works in HAVING, but raises an error in WHERE
SELECT e.department_id, AVG(e.salary) AS avg_sal
FROM   employees e
GROUP  BY e.department_id
HAVING AVG(e.salary) > 8000;
SELECT e.department_id FROM employees e WHERE AVG(e.salary) > 8000 GROUP BY e.department_id;

c027.try_sql:
-- A GROUP BY column need not be in SELECT (OK), but a SELECT column must be in GROUP BY (error)
SELECT COUNT(*) AS cnt FROM employees e GROUP BY e.department_id;
SELECT e.department_id, e.job_title, COUNT(*) AS cnt
FROM   employees e
GROUP  BY e.department_id;

c028.try_sql:
-- Two levels work; a plain column next to MAX(AVG(...)) raises an error
SELECT MAX(AVG(e.salary)) AS max_avg FROM employees e GROUP BY e.department_id;
SELECT e.department_id, MAX(AVG(e.salary)) FROM employees e GROUP BY e.department_id;

c300.try_sql:
-- A SELECT alias works in ORDER BY, but WHERE runs earlier and does not know it
SELECT e.last_name, e.salary * 12 AS annual FROM employees e ORDER BY annual DESC;
SELECT e.last_name, e.salary * 12 AS annual FROM employees e WHERE annual > 100000;

c301.try_sql:
-- Without GROUP BY the whole table is one group: one row or none
SELECT COUNT(*) AS cnt FROM employees e HAVING COUNT(*) > 5;
SELECT COUNT(*) AS cnt FROM employees e HAVING COUNT(*) > 50;

c302.try_sql:
-- promotions is empty: one row without GROUP BY, zero rows with GROUP BY
SELECT COUNT(*) AS cnt, SUM(p.discount_pct) AS s, MAX(p.discount_pct) AS mx FROM promotions p;
SELECT COUNT(*) AS cnt FROM promotions p GROUP BY p.promo_name;

c1303.try_sql:
-- The workaround works, COUNT with two arguments raises an error
SELECT COUNT(*) AS pairs
FROM   (SELECT DISTINCT e.department_id, e.job_title FROM employees e);
SELECT COUNT(DISTINCT e.department_id, e.job_title) FROM employees e;

c1304.try_sql:
-- A constant is never NULL, and NULL always is
SELECT COUNT(*) AS star, COUNT(1) AS one, COUNT('x') AS x, COUNT(NULL) AS nul
FROM   employees e;

c1306.try_sql:
-- Without GROUP BY: ORA-00937; with GROUP BY but no job_title: ORA-00979
SELECT e.department_id, COUNT(*) FROM employees e;
SELECT e.department_id, e.job_title, COUNT(*) FROM employees e GROUP BY e.department_id;

c1307.try_sql:
-- A row-level expression is OK, a group function in GROUP BY is an error
SELECT UPPER(e.job_title) AS job, COUNT(*) AS cnt FROM employees e GROUP BY UPPER(e.job_title);
SELECT COUNT(*) FROM employees e GROUP BY COUNT(*);
